class Solution:
    def minEatingSpeed(self, piles: list[int], h: int) -> int:
        lo, hi = 1, max(piles)
        while lo < hi:
            mid = (lo + hi) // 2
            hours = 0
            for p in piles:
                hours += math.ceil(p / mid)  # viz:pile
            if hours <= h:  # viz:test
                hi = mid  # viz:fast_enough
            else:
                lo = mid + 1  # viz:too_slow
        return lo  # viz:done
